import {adoptDefaults,effectiveActivity} from './activity-policy-e14b41d62339.mjs';
export function createSetup({getState,tasks,e,catalog,editSkill,editPlan}){
 async function open(){const s=getState(),step=Math.min(s.setupProgress.step,2),titles=['确认活动与类别','培养与关联','这一阶段，可稍后再定'];
  await tasks.open({id:'setup:step'+step,kind:'setup',title:(step+1)+' / 3 · '+titles[step],initial:{},submit:step===2?'完成初始设置':'确认并继续',
   body:()=>{
    if(step===0)return '<p>默认活动可以直接开始；需要时再细分。</p><div class="setup-steps">'+s.activityGroups.map(g=>'<section><h3>'+e(g.name)+'</h3><p>'+s.activities.filter(a=>a.groupId===g.id&&!a.archived).map(a=>e(a.name)).join('、')+'</p><button type="button" class="text-button" data-action="setup-new-activity" data-id="'+e(g.id)+'">＋ 自建子活动</button></section>').join('')+'</div>';
    if(step===1){const eligible=s.activities.filter(a=>!a.archived&&!a.mainSkillId&&!a.explicitlyExcluded&&a.growthMode!=='inherit'&&['group-study','group-exercise'].includes(a.groupId));return '<p>确认后新开始的活动使用这里的去向，旧记录和当前计时保持。</p>'+s.activities.filter(a=>!a.archived).map(a=>{const p=effectiveActivity(s,a);return '<div class="section-title"><span>'+e(a.name)+' → '+e(s.skills.find(k=>k.id===p.mainSkillId)?.name??'仅记录时间')+'</span><button type="button" class="text-button" data-action="setup-edit-activity" data-id="'+e(a.id)+'">修改</button></div>';}).join('')+(eligible.length?'<details open class="form-details"><summary>采用默认培养 · 只改你选中的项</summary><p class="quiet-note">旧版无法区分未配置与主动仅记时间；未勾选的保持原样。</p>'+eligible.map(a=>'<label class="check"><input type="checkbox" name="adoptIds" value="'+e(a.id)+'">'+e(a.name)+' → '+(a.groupId==='group-study'?'学习积累':'运动积累')+'</label>').join('')+'</details>':'')+'<button type="button" class="secondary" data-action="setup-new-skill">＋ 新建具体培养项</button>';}
    const plan=s.plans.find(p=>p.id===s.setupProgress.planId);return '<p>不建阶段也能继续记录；目标与培养可以以后完善。</p>'+(plan?'<h3>已保存：'+e(plan.title)+'</h3><button type="button" class="secondary" data-action="setup-edit-plan" data-id="'+e(plan.id)+'">查看或修改这个阶段</button>':'<button type="button" class="secondary" data-action="setup-new-plan">建立一个阶段</button>')+'<p class="quiet-note">关闭保留这一步，完成后仍可从设置进入。</p>';
   },onSave:async(f,{commit})=>{await commit(state=>{if(state.setupProgress.step>step)return state;let next=step===1?adoptDefaults(state,f.getAll('adoptIds')):state;next.setupProgress.step=step+1;next.setupProgress.confirmed=[...new Set([...next.setupProgress.confirmed,step])];if(step===2)next.settings.onboarding='done';return next;});},onSaved:step<2?open:null
  });
 }
 return {open,actions:{'setup-new-activity':id=>catalog.edit(null,{groupId:id,onReturn:open}),'setup-edit-activity':id=>catalog.edit(id,{onReturn:open}),'setup-new-skill':()=>editSkill({onReturn:open}),'setup-new-plan':()=>editPlan(null,{onReturn:open,setup:true}),'setup-edit-plan':id=>editPlan(id,{onReturn:open,setup:true})}};
}
